逐位考虑：对第 k 位，统计满足 (Aᵢ + Aⱼ) 在该位为 1 的数对 (i, j) 个数，若为奇数则该位答案置 1。参考程序：

```cpp
#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const int MAXN = 1e6 + 10;
int n, a[MAXN];
ll x[MAXN];
int main() {
    cin >> n;
    for (int i = 0; i < n; i++) {
        cin >> a[i];
    }
    ll ans = 0;
    for (int k = 0; k <= 30; k++) {
        ll bit = 1LL << k;
        ll mask = bit << 1;
        for (int i = 0; i < n; i++) {
            x[i] = a[i] % mask;
        }
        sort(x, x + n);
        ll cnt = 0;
        ll L1 = bit, R1 = mask;
        ll L2 = 3 * bit, R2 = mask * 2;
        for (int i = 0; i < n; i++) {
            ll v = x[i];
            cnt += upper_bound(x, x + n, R1 - 1 - v) - lower_bound(x, x + n, L1 - v);
            cnt += upper_bound(x, x + n, R2 - 1 - v) - lower_bound(x, x + n, L2 - v);
        }
        if (cnt % 2 == 1) {
            ans |= bit;
        }
    }
    cout << ans << endl;
    return 0;
}
```

a、b、c 可达 10¹⁰⁰⁰，需用高精度加法。参考程序：

```cpp
#include <bits/stdc++.h>
using namespace std;
string addBig(string a, string b) {
    int i = a.size() - 1, j = b.size() - 1;
    int carry = 0;
    string result = "";
    while (i >= 0 || j >= 0 || carry) {
        int sum = carry;
        if (i >= 0) sum += a[i--] - '0';
        if (j >= 0) sum += b[j--] - '0';
        result += (sum % 10) + '0';
        carry = sum / 10;
    }
    reverse(result.begin(), result.end());
    return result;
}
int main() {
    string a, b, c;
    cin >> a >> b >> c;
    string ans = addBig(addBig(a, b), c);
    cout << ans << endl;
    return 0;
}
```
